import { ImageResponse } from 'next/og'

/**
 * Serves /og.png — the 1200×630 social preview card — generated at build
 * time from this file. (The GitHub push route used for this repo accepts
 * text files only, so the card is generated by the app itself instead of
 * being committed as a binary. A PIL-rendered copy of the same design is
 * kept in the local tree as og-reference-pil.png.)
 */
export const dynamic = 'force-static'

const GREEN = '#00be6e'
const MUTED = '#a8baaf'

export function GET() {
  return new ImageResponse(
    (
      <div
        style={{
          width: '100%',
          height: '100%',
          display: 'flex',
          flexDirection: 'column',
          backgroundColor: '#0d1610',
          borderLeft: '14px solid #00be6e',
          padding: '56px 48px 48px 70px',
          fontFamily: 'sans-serif',
        }}
      >
        <div
          style={{
            color: GREEN,
            fontSize: 30,
            fontWeight: 700,
            letterSpacing: 4,
          }}
        >
          FROM MONEY IN AMERICA
        </div>
        <div
          style={{
            color: '#f5f8f6',
            fontSize: 168,
            fontWeight: 800,
            lineHeight: 1.05,
            marginTop: 18,
          }}
        >
          Nkap
        </div>
        <div
          style={{
            color: '#f5f8f6',
            fontSize: 56,
            fontWeight: 700,
            marginTop: 26,
          }}
        >
          Compare what your family
        </div>
        <div style={{ color: GREEN, fontSize: 56, fontWeight: 700 }}>
          actually receives.
        </div>
        <div style={{ color: MUTED, fontSize: 31, marginTop: 30 }}>
          Every fee and the hidden exchange-rate margin —
        </div>
        <div style={{ color: MUTED, fontSize: 31 }}>
          ranked by what arrives, never by what we earn.
        </div>
        <div
          style={{
            color: '#f5f8f6',
            fontSize: 29,
            fontWeight: 700,
            marginTop: 'auto',
          }}
        >
          freenkap.com
        </div>
      </div>
    ),
    { width: 1200, height: 630 },
  )
}
